@page "/board"
@using sv_3f7223f9ac1d411ba7dd0c68973351b4.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (loading)
{
    <p class="board-loading">Loading tasks...</p>
}
else if (error is not null)
{
    <div class="board-error">
        <p>@error</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats TotalCount="allTasks.Count"
                TodoCount="AllTodo.Count"
                InProgressCount="AllInProgress.Count"
                DoneCount="AllDone.Count"
                OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchText="@searchText" OnSearchChanged="text => { searchText = text; }" />

    <div class="board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="FilteredTodo"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     OnMoveRight="task => MoveTask(task, &quot;In Progress&quot;)"
                     OnAddTask="data => AddTask(data, &quot;To Do&quot;)" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="FilteredInProgress"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     OnMoveLeft="task => MoveTask(task, &quot;To Do&quot;)"
                     OnMoveRight="task => MoveTask(task, &quot;Done&quot;)"
                     OnAddTask="data => AddTask(data, &quot;In Progress&quot;)" />

        <BoardColumn ColumnName="Done"
                     Tasks="FilteredDone"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     OnMoveLeft="task => MoveTask(task, &quot;In Progress&quot;)"
                     OnAddTask="data => AddTask(data, &quot;Done&quot;)" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool loading = true;
    private string? error;

    // Unfiltered column lists (used for stats)
    private List<TaskItem> AllTodo => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> AllInProgress => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> AllDone => allTasks.Where(t => t.Status == "Done").ToList();

    // Filtered column lists (used for display)
    private List<TaskItem> FilteredTodo => ApplySearch(AllTodo);
    private List<TaskItem> FilteredInProgress => ApplySearch(AllInProgress);
    private List<TaskItem> FilteredDone => ApplySearch(AllDone);

    private List<TaskItem> ApplySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;

        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        loading = true;
        error = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            error = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            // CreateTaskAsync doesn't accept status, so update if not default "To Do"
            if (status != "To Do")
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, status);
                created = created with { Status = status };
            }
            allTasks.Add(created);
        }
        catch (Exception ex)
        {
            error = $"Failed to add task: {ex.Message}";
        }
    }
}

